export async function onRequest(context) {
  const { request, env } = context;
  const url = new URL(request.url);

  if (url.searchParams.get('go') !== '1') {
    return json({ hint: '访问 /api/import?go=1 执行导入', records: BACKUP.records.length });
  }

  const token = String(BACKUP.token || '').trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/.test(token)) return json({ error: 'bad token' }, 400);

  const existing = await env.DB
    .prepare('SELECT COUNT(*) AS n FROM records WHERE user_id = ?')
    .bind(token)
    .first();
  const force = url.searchParams.get('force') === '1';
  if (existing && existing.n > 0 && !force) {
    return json({ error: '该账户已有数据，未执行', count: existing.n, hint: '加 &force=1 覆盖' }, 409);
  }

  const stmts = [];
  const insRec = env.DB.prepare(
    `INSERT INTO records (id, user_id, type, amount, category, detail, is_family_card, timestamp, created_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
     ON CONFLICT(id) DO UPDATE SET
       type=excluded.type, amount=excluded.amount, category=excluded.category,
       detail=excluded.detail, is_family_card=excluded.is_family_card, timestamp=excluded.timestamp`
  );
  for (const r of BACKUP.records) {
    stmts.push(insRec.bind(
      String(r.id), token, String(r.type), Number(r.amount), String(r.category),
      r.detail == null ? null : String(r.detail),
      r.is_family_card ? 1 : 0, String(r.timestamp), String(r.created_at || r.timestamp)
    ));
  }

  if (BACKUP.settings && typeof BACKUP.settings.initial_balance !== 'undefined') {
    stmts.push(env.DB.prepare(
      `INSERT INTO user_settings (user_id, initial_balance) VALUES (?, ?)
       ON CONFLICT(user_id) DO UPDATE SET initial_balance = excluded.initial_balance`
    ).bind(token, Number(BACKUP.settings.initial_balance)));
  }

  const insTg = env.DB.prepare(
    `INSERT INTO month_targets (user_id, year, month, target) VALUES (?, ?, ?, ?)
     ON CONFLICT(user_id, year, month) DO UPDATE SET target = excluded.target`
  );
  for (const t of (BACKUP.targets || [])) {
    stmts.push(insTg.bind(token, Number(t.year), Number(t.month), Number(t.target)));
  }

  const CHUNK = 50;
  let done = 0;
  for (let i = 0; i < stmts.length; i += CHUNK) {
    await env.DB.batch(stmts.slice(i, i + CHUNK));
    done += Math.min(CHUNK, stmts.length - i);
  }

  const after = await env.DB
    .prepare('SELECT COUNT(*) AS n FROM records WHERE user_id = ?')
    .bind(token)
    .first();

  return json({ ok: true, executed: done, records_now: after ? after.n : null, message: '导入完成，请刷新 App' });
}

function json(obj, status) {
  return new Response(JSON.stringify(obj, null, 2), {
    status: status || 200,
    headers: { 'Content-Type': 'application/json; charset=utf-8' },
  });
}
